package com.hssa.auth.entity; import jakarta.persistence.*; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime; import java.util.UUID; @Entity @Table(name = "refresh_tokens", schema = "auth") @Getter @Setter @NoArgsConstructor @AllArgsConstructor public class RefreshToken { @Id @GeneratedValue(strategy = GenerationType.UUID) @Column(name = "id", updatable = false, nullable = false) private UUID id; @ManyToOne(fetch = FetchType.LAZY) @JoinColumn(name = "user_id", nullable = false) private User user; @Column(name = "token", nullable = false, unique = true, columnDefinition = "TEXT") private String token; @Column(name = "device_name", length = 200) private String deviceName; @Column(name = "device_type", length = 100) private String deviceType; @Column(name = "operating_system", length = 100) private String operatingSystem; @Column(name = "browser", length = 100) private String browser; @Column(name = "ip_address", columnDefinition = "inet") private String ipAddress; @Column(name = "user_agent", columnDefinition = "TEXT") private String userAgent; @Column(name = "expires_at", nullable = false) private LocalDateTime expiresAt; @Column(name = "revoked_at") private LocalDateTime revokedAt; @Column(name = "is_revoked", nullable = false) private boolean isRevoked = false; @CreationTimestamp @Column(name = "created_at", nullable = false, updatable = false) private LocalDateTime createdAt; }
